function editableSequences(geometry){const sequences=[];const add=(coordinates,closed=false)=>{if(Array.isArray(coordinates)&&coordinates.length)sequences.push({coordinates,closed})};if(geometry?.type==='LineString')add(geometry.coordinates);else if(geometry?.type==='MultiLineString')geometry.coordinates.forEach(line=>add(line));else if(geometry?.type==='Polygon')geometry.coordinates.forEach(ring=>add(ring,true));else if(geometry?.type==='MultiPolygon')geometry.coordinates.forEach(polygon=>polygon.forEach(ring=>add(ring,true)));return sequences}
function uniqueVertexCount(sequence){return Math.max(0,sequence.coordinates.length-(sequence.closed&&coordinateEqual(sequence.coordinates[0],sequence.coordinates.at(-1))?1:0))}
function closeEditedSequence(sequence){if(!sequence.closed)return;const coordinates=sequence.coordinates;if(!coordinates.length)return;if(coordinates.length===1)coordinates.push(cloneJson(coordinates[0]));else coordinates[coordinates.length-1]=cloneJson(coordinates[0])}
function vertexHandleIcon(selected=false){return L.divIcon({className:`geometry-handle${selected?' selected':''}`,html:'<span></span>',iconSize:[20,20],iconAnchor:[10,10]})}
function midpointHandleIcon(){return L.divIcon({className:'geometry-midpoint',html:'<span></span>',iconSize:[14,14],iconAnchor:[7,7]})}
let generatedEdit=null,generatedGeometryHandles=[],selectedGeneratedVertex=null;
function clearGeneratedGeometryHandles(){generatedGeometryHandles.forEach(handle=>map.removeLayer(handle));generatedGeometryHandles=[];selectedGeneratedVertex=null;$('#removeVertex').classList.add('hidden')}
function renderGeneratedEditShape(){if(!generatedEdit)return;if(generatedEdit.shape)map.removeLayer(generatedEdit.shape);generatedEdit.shape=L.geoJSON(generatedEdit.feature,{pane:'fieldPane',interactive:false,style:{color:'#286fc0',weight:4,fillColor:'#286fc0',fillOpacity:.12,dashArray:'7 4',className:'generated-edit-shape'}}).addTo(map)}
function selectGeneratedVertex(sequence,index,marker){selectedGeneratedVertex={sequence,index};generatedGeometryHandles.filter(handle=>handle._omapVertex).forEach(handle=>handle.setIcon(vertexHandleIcon(handle===marker)));$('#removeVertex').classList.remove('hidden')}
function pushGeneratedUndo(){if(!generatedEdit)return;generatedEdit.undo.push(cloneJson(generatedEdit.feature.geometry));if(generatedEdit.undo.length>30)generatedEdit.undo.shift();$('#undoVertex').disabled=false}
function renderGeneratedGeometryHandles(){if(!generatedEdit)return;clearGeneratedGeometryHandles();for(const sequence of editableSequences(generatedEdit.feature.geometry)){const count=uniqueVertexCount(sequence);for(let index=0;index<count;index++){const coordinate=sequence.coordinates[index],vertex=L.marker([coordinate[1],coordinate[0]],{pane:'fieldPane',icon:vertexHandleIcon(),draggable:true,zIndexOffset:1200,title:'Flytta eller välj hörn'}).addTo(map);vertex._omapVertex=true;vertex.on('dragstart',pushGeneratedUndo);vertex.on('drag',event=>{const point=event.target.getLatLng(),existing=sequence.coordinates[index];sequence.coordinates[index]=[point.lng,point.lat,...existing.slice(2)];closeEditedSequence(sequence);renderGeneratedEditShape()});vertex.on('dragend',()=>renderGeneratedGeometryHandles());vertex.on('click',event=>{L.DomEvent.stopPropagation(event);selectGeneratedVertex(sequence,index,vertex)});generatedGeometryHandles.push(vertex);if(!sequence.closed&&index===count-1)continue;const nextIndex=(index+1)%count,a=sequence.coordinates[index],b=sequence.coordinates[nextIndex],midpoint=L.marker([(a[1]+b[1])/2,(a[0]+b[0])/2],{pane:'fieldPane',icon:midpointHandleIcon(),zIndexOffset:1100,title:'Lägg till hörn'}).addTo(map);midpoint.on('click',event=>{L.DomEvent.stopPropagation(event);pushGeneratedUndo();const insertAt=index+1,newCoordinate=[(a[0]+b[0])/2,(a[1]+b[1])/2];sequence.coordinates.splice(insertAt,0,newCoordinate);closeEditedSequence(sequence);renderGeneratedEditShape();renderGeneratedGeometryHandles()});generatedGeometryHandles.push(midpoint)}}}
function closeGeneratedEditor({rerender=true}={}){if(!generatedEdit)return;const layerType=generatedEdit.layerType;if(generatedEdit.shape)map.removeLayer(generatedEdit.shape);clearGeneratedGeometryHandles();generatedEdit=null;document.body.classList.remove('generated-geometry-editing');$('#editBar').classList.add('hidden');$('#removeVertex').classList.add('hidden');$('#undoVertex').disabled=false;if(rerender)generatedLayerConfig(layerType)?.render()}
function startGeneratedGeometryEdit(layerType,feature){if(recording)return toast('Slutför eller avbryt pågående objekt först');if(!editableSequences(feature.geometry).length)return toast('Den här geometritypen kan inte redigeras ännu');if(mode!=='manual')setMode('manual');clearSelection();map.closePopup();generatedEdit={layerType,feature,startGeometry:cloneJson(feature.geometry),sourceGeometry:cloneJson(feature.properties?.originalGeometry||feature.geometry),undo:[],shape:null};document.body.classList.add('generated-geometry-editing');$('#undoVertex').classList.remove('hidden');$('#undoVertex').disabled=true;$('#removeVertex').classList.add('hidden');$('#cancelEdit').classList.remove('hidden');$('#finishEdit').classList.remove('hidden');$('#finishEdit').textContent='Spara form';$('#deleteFeature').classList.add('hidden');$('#editBar').classList.remove('hidden');renderGeneratedEditShape();renderGeneratedGeometryHandles();toast('Dra blå hörn · tryck vita punkter för fler hörn')}
async function finishGeneratedGeometryEdit(){if(!generatedEdit)return;const {layerType,feature,sourceGeometry}=generatedEdit,p=feature.properties||(feature.properties={});if(!p.originalGeometry)p.originalGeometry=sourceGeometry;p.status='locally-edited';p.editedAt=new Date().toISOString();closeGeneratedEditor({rerender:false});await persistGeneratedLayer(layerType);toast('Formen sparades lokalt')}
function cancelGeneratedGeometryEdit(){if(!generatedEdit)return;generatedEdit.feature.geometry=cloneJson(generatedEdit.startGeometry);closeGeneratedEditor();toast('Formändringen avbröts')}
function undoGeneratedGeometryEdit(){if(!generatedEdit||!generatedEdit.undo.length)return;generatedEdit.feature.geometry=generatedEdit.undo.pop();renderGeneratedEditShape();renderGeneratedGeometryHandles();$('#undoVertex').disabled=!generatedEdit.undo.length}
function removeSelectedGeneratedVertex(){if(!generatedEdit||!selectedGeneratedVertex)return;const {sequence,index}=selectedGeneratedVertex,count=uniqueVertexCount(sequence),minimum=sequence.closed?3:2;if(count<=minimum)return toast(`Minst ${minimum} hörn måste finnas kvar`);pushGeneratedUndo();sequence.coordinates.splice(index,1);closeEditedSequence(sequence);renderGeneratedEditShape();renderGeneratedGeometryHandles()}
document.addEventListener('click',async event=>{const editButton=event.target.closest?.('[data-generated-edit]');if(editButton){const feature=generatedFeature(editButton.dataset.generatedEdit,editButton.dataset.generatedId);if(feature)startGeneratedGeometryEdit(editButton.dataset.generatedEdit,feature);return}const actionButton=event.target.closest?.('[data-generated-action]');if(!actionButton)return;const layerType=actionButton.dataset.generatedLayer,feature=generatedFeature(layerType,actionButton.dataset.generatedId);if(!feature)return;const action=actionButton.dataset.generatedAction;if(action==='exclude'){if(generatedStatus(feature)==='excluded')return toast('Objektet är redan uteslutet');if(!feature.properties.originalGeometry)feature.properties.originalGeometry=cloneJson(feature.geometry);feature.properties.status='locally-excluded';feature.properties.editedAt=new Date().toISOString()}else if(action==='reset')resetGeneratedFeature(feature);map.closePopup();await persistGeneratedLayer(layerType);toast(action==='exclude'?'Objektet uteslöts lokalt':'Originalet återställdes')});

function item(cat,id){return catalog[cat].find(x=>x[0]===id)||[id,'',id]}
function name(cat,id){return item(cat,id)[2]}
function objectEntries(){return[['point',state.observations],['line',state.tracks],['area',state.areas]].flatMap(([cat,list])=>list.map(obj=>({cat,obj})))}
function pendingEntries(){return objectEntries().filter(({obj})=>obj.syncStatus!=='submitted')}
function markObjectChanged(obj){if(obj.syncStatus==='submitted'){obj.version=Number(obj.version||1)+1;obj.syncStatus='local';delete obj.submissionId;delete obj.submittedAt}}
function refreshLocalDraftMeta(){const all=objectEntries(),pending=all.filter(({obj})=>obj.syncStatus!=='submitted').length,submitted=all.length-pending;$('#objectCount').textContent=`${all.length} lokala objekt`;$('#localDraftsMeta').textContent=`${pending} inte insända${submitted?` · ${submitted} insända`:''} · endast på denna enhet`;$('#reviewSubmissionButton').disabled=pending===0}
function save(){localStorage.setItem('omapmaker.global',JSON.stringify(state));localStorage.setItem('omapmaker.live',JSON.stringify(state));localStorage.setItem('omapmaker.prefs',JSON.stringify(prefs));refreshLocalDraftMeta()}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),1900)}

function publicationFeature(cat,obj){
  let geometry;
  if(cat==='point')geometry={type:'Point',coordinates:obj.coordinates.slice(0,2)};
  else if(cat==='line')geometry={type:'LineString',coordinates:obj.coordinates.map(coordinate=>coordinate.slice(0,2))};
  else{const ring=obj.coordinates.map(coordinate=>coordinate.slice(0,2));if(ring.length&&JSON.stringify(ring[0])!==JSON.stringify(ring[ring.length-1]))ring.push([...ring[0]]);geometry={type:'Polygon',coordinates:[ring]}}
  return{type:'Feature',id:obj.observationId,properties:{clientObservationId:obj.observationId,version:Number(obj.version||1),category:cat,objectType:obj.objectType,symbol:obj.symbol,source:obj.source||'unknown',quality:obj.quality||'unverified',accuracy:cat==='point'?Number(obj.accuracy||0):null,createdAt:obj.createdAt||null},geometry}
}
function entryPosition(cat,obj){const coordinate=cat==='point'?obj.coordinates:obj.coordinates[0];const points=cat==='point'?'punkt':`${obj.coordinates.length} mätpunkter`;return`${Number(coordinate[1]).toFixed(5)}, ${Number(coordinate[0]).toFixed(5)} · ${points}`}
let submissionCandidates=[],clientSubmissionId=null;
function updateSubmissionControls(){const checked=[...document.querySelectorAll('#submissionList input:checked')];$('#submissionSelectionCount').textContent=`${checked.length} valda`;$('#submitObservations').disabled=!checked.length||!$('#publishConsent').checked;const all=[...document.querySelectorAll('#submissionList input')];$('#selectAllDrafts').textContent=all.length&&checked.length===all.length?'Avmarkera alla':'Välj alla opublicerade'}
function openSubmissionSheet(){
  submissionCandidates=pendingEntries();if(!submissionCandidates.length)return toast('Alla lokala objekt är redan insända');
  $('#layersSheet').close();const list=$('#submissionList');list.innerHTML='';$('#publishConsent').checked=false;$('#submissionStatus').textContent='';clientSubmissionId=null;
  submissionCandidates.forEach(({cat,obj},index)=>{const label=document.createElement('label'),input=document.createElement('input'),text=document.createElement('span'),title=document.createElement('b'),detail=document.createElement('small');input.type='checkbox';input.dataset.index=String(index);input.onchange=updateSubmissionControls;title.textContent=`${name(cat,obj.objectType)} · ${cat==='point'?'punkt':cat==='line'?'linje':'område'}`;detail.textContent=`${entryPosition(cat,obj)} · ${obj.source==='gps'?'GPS':'manuellt'}${obj.version>1?` · version ${obj.version}`:''}`;text.append(title,detail);label.append(input,text);list.append(label)});
  updateSubmissionControls();$('#submissionSheet').showModal()
}
$('#reviewSubmissionButton').onclick=openSubmissionSheet;
$('#selectAllDrafts').onclick=()=>{const inputs=[...document.querySelectorAll('#submissionList input')],select=inputs.some(input=>!input.checked);inputs.forEach(input=>input.checked=select);updateSubmissionControls()};
$('#publishConsent').onchange=updateSubmissionControls;
$('#submitObservations').onclick=async()=>{
  const selected=[...document.querySelectorAll('#submissionList input:checked')].map(input=>submissionCandidates[Number(input.dataset.index)]);if(!selected.length||!$('#publishConsent').checked)return;
  const button=$('#submitObservations'),status=$('#submissionStatus');button.disabled=true;button.textContent='Skickar…';status.textContent='Observationerna skickas till serverns automatiska evidensmodell…';clientSubmissionId=clientSubmissionId||crypto.randomUUID();
  try{const response=await fetch('/api/submissions',{method:'POST',headers:{'Content-Type':'application/json','X-OMapMaker-Device':deviceId},body:JSON.stringify({clientSubmissionId,features:selected.map(({cat,obj})=>publicationFeature(cat,obj))})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Observationerna kunde inte skickas');selected.forEach(({obj})=>{obj.syncStatus='submitted';obj.submissionId=result.id;obj.submittedAt=result.createdAt});save();status.textContent=result.candidateCount?`Klart: ${result.featureCount} observationer behandlade · ${result.candidateCount} globala punktobjekt uppdaterade.`:`Klart: ${result.featureCount} observationer sparade som evidens. Automatisk sammanslagning av linjer och områden kommer senare.`;button.textContent='Insända';localStorage.setItem('omapmaker.publishNoticeAccepted','true');await loadGlobalObjects();if(layerPrefs.evidence)await loadEvidence();setTimeout(()=>$('#submissionSheet').close(),1800)}catch(error){status.textContent=error.message;button.disabled=false;button.textContent='Försök igen'}
};
function pointSvg(id){
  const symbol=String(catalog.point.find(entry=>entry[0]===id)?.[1]||id),black='#181b19',brown='#9b5b35',green='#19834a',blue='#168cab';
  if(symbol==='206')return `<svg class="symbol-svg" viewBox="0 0 24 24"><circle cx="12" cy="12" r="4.2" fill="${black}"/></svg>`;
  if(symbol==='204')return `<svg class="symbol-svg" viewBox="0 0 24 24"><path d="M7 18 5 10l5-6 7 3 2 8-5 5z" fill="${black}"/></svg>`;
  if(symbol==='109')return `<svg class="symbol-svg" viewBox="0 0 24 24"><circle cx="12" cy="12" r="5" fill="none" stroke="${brown}" stroke-width="2.2"/></svg>`;
  if(symbol==='202')return `<svg class="symbol-svg" viewBox="0 0 24 24"><path d="M7 7v7l5 4 5-4V7" fill="none" stroke="${brown}" stroke-width="2.2"/></svg>`;
  if(symbol==='524')return `<svg class="symbol-svg" viewBox="0 0 24 24"><path d="m6 18 6-12 6 12M8 14h8" fill="none" stroke="${black}" stroke-width="2"/></svg>`;
  if(symbol==='311')return `<svg class="symbol-svg" viewBox="0 0 24 24"><circle cx="12" cy="12" r="5" fill="none" stroke="${blue}" stroke-width="2.2"/></svg>`;
  return `<svg class="symbol-svg" viewBox="0 0 24 24"><path d="M6 7l12 10M18 7 6 17" stroke="${green}" stroke-width="2.2"/></svg>`;
}
function pointIcon(id){const size=25*symbolScale();return L.divIcon({className:'omap-symbol',html:pointSvg(id),iconSize:[size,size],iconAnchor:[size/2,size/2]})}
function isomLineStyle(symbol,feature=null){const scale=symbolScale(),value=String(symbol||'506');if(value==='502')return{color:'#111',weight:feature?wideRoadDimensions(feature).outer:7*scale};if(value==='503')return{color:'#111',weight:3.5*scale};if(value==='504')return{color:'#111',weight:3*scale,dashArray:`${12*scale} ${4*scale}`};if(value==='505')return{color:'#111',weight:2.5*scale,dashArray:`${9*scale} ${5*scale}`};if(value==='507')return{color:'#111',weight:1.8*scale,dashArray:`${2*scale} ${4*scale} ${2*scale} ${8*scale}`};if(value==='304')return{color:'#168cab',weight:3.4*scale};if(value==='307')return{color:'#8d5b36',weight:3*scale,dashArray:`${8*scale} ${5*scale}`};if(value==='201')return{color:'#181b19',weight:5*scale};if(value==='516')return{color:'#181b19',weight:3*scale,dashArray:`${3*scale} ${5*scale}`};if(value==='513.1')return{color:'#181b19',weight:4*scale};return{color:'#111',weight:1.8*scale,dashArray:`${5*scale} ${4*scale}`}}
function lineStyle(id){return isomLineStyle(catalog.line.find(entry=>entry[0]===id)?.[1]||id)}
function areaStyle(id){const symbol=catalog.area.find(entry=>entry[0]===id)?.[1]||id;if(String(symbol)==='309')return{color:'#168cab',weight:Math.max(1,symbolScale()),fillColor:'#bce2df',fillOpacity:.5,dashArray:'5 4'};return isomAreaStyle(symbol,{boundary:id==='forbidden'?'clear':undefined})}
function latlngs(coords){return coords.map(c=>[c[1],c[0]])}
function clearSelection(){handles.forEach(h=>map.removeLayer(h));handles=[];selected=null;$('#editBar').classList.add('hidden')}
function setFeatureLayerLatLngs(layer,coordinates){if(layer.setLatLngs)layer.setLatLngs(latlngs(coordinates));else layer.eachLayer?.(child=>child.setLatLngs?.(latlngs(coordinates)))}
function selectFeature(cat,obj,layer){if(mode!=='manual'||recording||generatedEdit)return;clearSelection();selected={cat,obj,layer};if(cat!=='point')obj.coordinates.forEach((c,i)=>{const h=L.marker([c[1],c[0]],{icon:L.divIcon({className:'',html:'<span style="display:block;width:18px;height:18px;border-radius:50%;background:#286fc0;border:3px solid white"></span>',iconSize:[18,18],iconAnchor:[9,9]}),draggable:true}).addTo(map);h.on('drag',e=>{const p=e.target.getLatLng();obj.coordinates[i]=[p.lng,p.lat,...obj.coordinates[i].slice(2)];setFeatureLayerLatLngs(layer,obj.coordinates)});h.on('dragend',()=>{markObjectChanged(obj);save()});handles.push(h)});$('#undoVertex').classList.add('hidden');$('#removeVertex').classList.add('hidden');$('#cancelEdit').classList.add('hidden');$('#finishEdit').classList.remove('hidden');$('#finishEdit').textContent='Klar';$('#deleteFeature').classList.remove('hidden');$('#editBar').classList.remove('hidden')}
function applyFieldPresentation(layer){if(layer.eachLayer)return layer.eachLayer(applyFieldPresentation);const el=layer.getElement?.();if(el){el.classList.toggle('foreground-hidden',!layerPrefs.objects);el.style.opacity=String(layerPrefs.opacity/100)}}
function renderPoint(o){const m=L.marker([o.coordinates[1],o.coordinates[0]],{pane:'fieldPane',icon:pointIcon(o.objectType||o.type),draggable:mode==='manual'}).addTo(map);m.on('add',()=>applyFieldPresentation(m));m.on('dragend',e=>{const p=e.target.getLatLng();o.coordinates=[p.lng,p.lat];o.source='manual-adjustment';markObjectChanged(o);save()});m.on('click',()=>selectFeature('point',o,m));layers.set(o.id,m);applyFieldPresentation(m)}
function renderLine(o){const symbol=String(o.symbol||item('line',o.objectType||o.type)[1]),outer=L.polyline(latlngs(o.coordinates),{pane:'fieldPane',...isomLineStyle(symbol)});let layer=outer;if(symbol==='502'){const inner=L.polyline(latlngs(o.coordinates),{pane:'fieldPane',interactive:false,color:'#b89b72',weight:Math.max(2,4*symbolScale()),opacity:1}),group=L.layerGroup([outer,inner]).addTo(map);group._omapWideRoad={outer,inner};layer=group}else outer.addTo(map);outer.on('add',()=>applyFieldPresentation(layer));outer.on('click',()=>selectFeature('line',o,layer));layers.set(o.id,layer);applyFieldPresentation(layer)}
function renderArea(o){const p=L.polygon(latlngs(o.coordinates),{pane:'fieldPane',...areaStyle(o.objectType||o.type)}).addTo(map);p.on('add',()=>applyFieldPresentation(p));p.on('click',()=>selectFeature('area',o,p));layers.set(o.id,p);applyFieldPresentation(p)}
state.observations.forEach(renderPoint);state.tracks.forEach(renderLine);state.areas.forEach(renderArea);
function refreshSymbolPresentation(){state.observations.forEach(o=>layers.get(o.id)?.setIcon(pointIcon(o.objectType||o.type)));state.tracks.forEach(o=>{const layer=layers.get(o.id),symbol=String(o.symbol||item('line',o.objectType||o.type)[1]);if(layer?._omapWideRoad){layer._omapWideRoad.outer.setStyle(isomLineStyle(symbol));layer._omapWideRoad.inner.setStyle({color:'#b89b72',weight:Math.max(2,4*symbolScale()),opacity:1})}else layer?.setStyle?.(isomLineStyle(symbol))});state.areas.forEach(o=>layers.get(o.id)?.setStyle(areaStyle(o.objectType||o.type)));renderLandCover();renderProjectContours();renderBuildings();renderPavedAreas();renderRoads();renderGlobalObjects()}
map.on('zoomend',()=>{if(workspace?.symbolDisplayMode==='print')refreshSymbolPresentation();else renderRoads()});

function labels(){
  const pointButton=$('#pointAction'), pointActive=recording?.cat==='point';
  $('#pointLabel').textContent=name('point',pointActive?recording.type:prefs.point);
  pointButton.classList.toggle('active-tool',pointActive);
  pointButton.querySelector('span').textContent=pointActive?'PLACERA PÅ KARTAN':'PLACERA';
  for(const cat of ['line','area']){
    const button=$(`#${cat}Action`), active=recording?.cat===cat, noun=name(cat,active?recording.type:prefs[cat]);
    button.classList.toggle('recording',active);
    button.querySelector('span').textContent=active?(recording.mode==='gps'?'MÄTER':'RITAR'):(mode==='gps'?'SPELA IN':'RITA');
    button.querySelector('b').textContent=active?`■ ${noun}`:noun;
  }
}
function setMode(next){
  if(recording?.mode==='gps'&&next!=='gps')return toast('Avsluta eller avbryt GPS-inspelningen först');
  if(recording){cancelDrawing(false)}
  clearSelection();mode=next;localStorage.setItem('omapmaker.mode',mode);
  document.body.classList.toggle('manual-mode',mode==='manual');document.body.classList.toggle('gps-mode',mode==='gps');
  $('#gpsMode').classList.toggle('active',mode==='gps');$('#manualMode').classList.toggle('active',mode==='manual');
  $('#modeHint').textContent=mode==='gps'?'GPS · Telefonens position':'MANUELLT · Rita på kartan';
  state.observations.forEach(o=>{const m=layers.get(o.id);mode==='manual'?m.dragging.enable():m.dragging.disable()});labels();
}
$('#gpsMode').onclick=()=>setMode('gps');$('#manualMode').onclick=()=>setMode('manual');

function identity(){const id=crypto.randomUUID();return{id,observationId:id,syncStatus:'local',version:1}}
function addPoint(ll,accuracy,source){if(source==='gps'&&accuracy>50)return toast(`GPS ±${Math.round(accuracy)} m · för osäkert`);const o={...identity(),objectType:prefs.point,symbol:item('point',prefs.point)[1],coordinates:[ll.lng,ll.lat],accuracy,source,quality:'unverified',createdAt:new Date().toISOString()};state.observations.push(o);renderPoint(o);save();toast(`${name('point',prefs.point)} sparad`)}
function showDrawingBar(){clearSelection();$('#undoVertex').classList.remove('hidden');$('#cancelEdit').classList.remove('hidden');$('#finishEdit').classList.remove('hidden');$('#finishEdit').textContent='Slutför';$('#deleteFeature').classList.add('hidden');$('#editBar').classList.remove('hidden')}
function updateTemp(){if(tempLayer)map.removeLayer(tempLayer);if(!currentCoords.length)return;tempLayer=recording.cat==='area'?L.polygon(latlngs(currentCoords),{...areaStyle(recording.type),className:'temp-shape'}).addTo(map):L.polyline(latlngs(currentCoords),{...lineStyle(recording.type),className:'temp-shape'}).addTo(map)}
function beginShape(cat){recording={mode,cat,type:prefs[cat]};currentCoords=[];showDrawingBar();labels();toast(mode==='gps'?`${name(cat,prefs[cat])} spelas in`:`Tryck ut ${cat==='line'?'linjen':'områdets hörn'}`)}
function finishDrawing(){if(!recording)return;const min=recording.cat==='area'?3:2;if(currentCoords.length<min)return toast(`Minst ${min} punkter behövs`);const obj={...identity(),objectType:recording.type,symbol:item(recording.cat,recording.type)[1],coordinates:[...currentCoords],source:recording.mode,quality:'unverified',createdAt:new Date().toISOString()};if(recording.cat==='line'){state.tracks.push(obj);renderLine(obj)}else{state.areas.push(obj);renderArea(obj)}cancelDrawing(false);save();toast('Objekt sparat')}
function cancelDrawing(message=true){if(tempLayer)map.removeLayer(tempLayer);tempLayer=null;recording=null;currentCoords=[];$('#editBar').classList.add('hidden');labels();if(message)toast('Ritningen avbröts')}
function action(cat){
  if(cat==='point'){if(mode==='manual'){recording={mode:'manual',cat:'point',type:prefs.point};labels();toast(`${name('point',prefs.point)} vald · tryck på kartan`)}else if(lastPosition)addPoint(lastPosition.latlng,lastPosition.accuracy,'gps');else toast('GPS söker position · försök igen strax');return}
  if(recording?.cat===cat)return finishDrawing();
  if(recording)return toast('Slutför eller avbryt pågående objekt först');
  if(mode==='gps'&&!lastPosition)return toast('GPS söker position · försök igen strax');
  if(mode==='gps'&&lastPosition.accuracy>50)return toast('GPS-kvaliteten är för låg');
  beginShape(cat);
}
$('#pointAction').onclick=()=>action('point');$('#lineAction').onclick=()=>action('line');$('#areaAction').onclick=()=>action('area');
map.on('click',e=>{if(mode!=='manual')return;if(recording?.cat==='point'){addPoint(e.latlng,0,'manual');recording=null;labels()}else if(recording?.mode==='manual'){currentCoords.push([e.latlng.lng,e.latlng.lat,0,Date.now(),null,null]);updateTemp()}});
