function startGps(){if(watchId!==null)return;if(!navigator.geolocation){toast('GPS stöds inte av webbläsaren');return}localStorage.setItem('omapmaker.gpsEnabled','true');$('#gpsQuality').className='';$('#gpsQuality span').textContent='GPS söker position…';watchId=navigator.geolocation.watchPosition(p=>{const ll=L.latLng(p.coords.latitude,p.coords.longitude);lastPosition={latlng:ll,accuracy:p.coords.accuracy};if(!gpsMarker){gpsMarker=L.circleMarker(ll,{radius:7,color:'#fff',weight:3,fillColor:'#2677c7',fillOpacity:1,className:'gps-position-marker'}).addTo(map);gpsCircle=L.circle(ll,{radius:p.coords.accuracy,className:'accuracy'}).addTo(map)}else{gpsMarker.setLatLng(ll);gpsCircle.setLatLng(ll).setRadius(p.coords.accuracy)}const [cls,label]=quality(p.coords.accuracy);$('#gpsQuality').className=cls;$('#gpsQuality span').textContent=label;if(recording?.mode==='gps'&&p.coords.accuracy<=50){currentCoords.push([p.coords.longitude,p.coords.latitude,p.coords.accuracy,Date.now(),p.coords.altitude,p.coords.altitudeAccuracy]);updateTemp()}},e=>{$('#gpsQuality').className='bad';$('#gpsQuality span').textContent=e.code===1?'GPS saknar tillstånd':'GPS kunde inte hämtas'},{enableHighAccuracy:true,maximumAge:0,timeout:15000});refreshGpsButton()}
function stopGps(){if(recording?.mode==='gps')return toast('Avsluta eller avbryt GPS-inspelningen först');if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;lastPosition=null;if(gpsMarker)map.removeLayer(gpsMarker);if(gpsCircle)map.removeLayer(gpsCircle);gpsMarker=null;gpsCircle=null;localStorage.setItem('omapmaker.gpsEnabled','false');$('#gpsQuality').className='';refreshGpsButton()}
