function startPrintAreaSelection(){if(!workspace)return;writeExportSettings();printAreaOriginalCenter=selectedPrintCenter?{...selectedPrintCenter}:null;$('#exportSheet').close();document.body.classList.add('print-area-mode');$('#printAreaPicker').hidden=false;const settings=printableSettingsFromForm(),center=selectedPrintCenter||workspace.center,bounds=printBounds(center,settings);map.fitBounds(bounds,{paddingTopLeft:[35,105],paddingBottomRight:[35,35],animate:false});printAreaMoveHandler=updatePrintAreaLayer;map.on('move',printAreaMoveHandler);updatePrintAreaLayer()}
